
-- Q1. What is the total revenue generated by male vs. female customers?

Select	gender, sum(purchased_amount)
from	customer
group by	gender;

-- Q2. Which customers used a discount but still spent more than the average purchase amount? 

select	customer_id
from	customer
where	discount_applied = 'Yes' 
and		purchase_amount > (select avg(purchase_amount) from customer);


-- Q3. Which are the top 5 products with the highest average review rating?

select items_purchased, avg(review_rating)
from	customers
group by	items_purchased
order by	avg(review_rating) desc
limit 5;

-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 

SELECT `Shipping Type`, avg(`Purchase Amount (USD)`)
FROM	customer
where	`Shipping Type` in ('Standard', 'Express')
group by `Shipping Type`;

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.

SELECT	`Subscription Status`, COUNT(`Customer ID`), AVG(`Purchase Amount (USD)`), SUM(`Purchase Amount (USD)`)
FROM	customer
GROUP BY	`Subscription Status`;

-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?

SELECT `Item Purchased`, ((SUM(CASE WHEN `Discount Applied` = 'Yes' THEN 1 ELSE 0 END)/ COUNT(`Item Purchased`)) * 100) As PurchaseRate
FROM	CUSTOMER
GROUP BY	`Item Purchased`
ORDER BY	PurchaseRate Desc
limit 5;

-- Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment. 
with customer_type as (
SELECT `Customer ID`, `Previous Purchases`,
CASE 
    WHEN `Previous Purchases` = 1 THEN 'New'
    WHEN `Previous Purchases` BETWEEN 2 AND 10 THEN 'Returning'
    ELSE 'Loyal'
    END AS customer_segment
FROM customer);

WITH CustomerSegment AS (
SELECT *, 	CASE WHEN `Previous Purchases`=1 THEN 'New'
			WHEN `Previous Purchases` BETWEEN 2 AND 10 THEN 'Returning'
            WHEN `Previous Purchases` > 10 THEN 'Loyal'
            END AS Segment
FROM	customer
)

SELECT	Segment, COUNT(`Customer ID`)
FROM 	CustomerSegment
GROUP BY	Segment;

or

SELECT
    Segment,
    COUNT(`Customer ID`) AS CustomerCount
FROM (
    SELECT *,
        CASE
            WHEN `Previous Purchases` = 1 THEN 'New'
            WHEN `Previous Purchases` BETWEEN 2 AND 10 THEN 'Returning'
            WHEN `Previous Purchases` > 10 THEN 'Loyal'
        END AS Segment
    FROM customer
) AS CustomerSegment
GROUP BY Segment;
SELECT VERSION();

-- Q8. What are the top 3 most purchased products within each category? 

WITH ProdductPurchase AS (
SELECT	Category, 
		`Item Purchased`, 
        COUNT(`Customer ID`) , 
        ROW_NUMBER() OVER (PARTITION BY category ORDER BY COUNT(`Customer ID`) DESC) AS ItemRank
FROM	CUSTOMER
GROUP BY	Category, `Item Purchased`)

SELECT	Category, 
		`Item Purchased`, 
        COUNT(`Customer ID`)
FROM	ProdductPurchase
WHERE	ItemRank <=3
 
-- Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?

SELECT	`Subscription Status`, COUNT(`Customer ID`)
FROM	CUSTOMER
WHERE	`Previous Purchases` > 5
GROUP BY	`Subscription Status`

-- Q10. What is the revenue contribution of each age group? 

SELECT	age_group, SUM(`Purchase Amount (USD)`)
FROM	CUSTOMER
GROUP BY	age_group;